INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-bean-introduction','菜豆（四季豆）传入中国','agriculture','point','approximate_year',NULL,NULL,'资料称四季豆于明末传入中国，具体年份未详。',1600,12,NULL,19211,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'菜豆原产中南美洲，明代随美洲作物交流传入中国，后来成为普遍栽培的食用豆类。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-cabbage-introduction','卷心菜（洋白菜）传入中国','agriculture','point','approximate_year',NULL,NULL,'资料称白菜于清代传入中国，具体年份未明。',1644,12,NULL,19739,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'卷心菜又称洋白菜或甘蓝，源自欧洲地中海地区，清代经海路传入中国并逐步成为常见蔬菜。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-carrot-introduction','胡萝卜传入中国','agriculture','point','approximate_year',NULL,NULL,'资料称宋代已有胡萝卜；南宋《绍兴本草》有相关记载，具体引入年份未详。',1127,12,NULL,13535,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'胡萝卜原产西亚，宋代已在中国栽培并见于本草记载，后来成为常见根菜。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-cashew-introduction','腰果传入中国','agriculture','point','approximate_year',NULL,NULL,'截图列入明清美洲作物，未给出确年；以明清之际1600年作为所述时期最早年份，表示年代框架而非确切引种年。',1600,12,NULL,19211,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'腰果原产美洲热带地区，随海上贸易传播至亚洲；在中国的引种和规模化栽培较晚，主要适应南方热带地区。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-cauliflower-introduction','花菜传入中国','agriculture','point','approximate_year',NULL,NULL,'清朝农业科技史年表记1895年花椰菜见载；采用该最早明确记载年份。',1895,12,NULL,22751,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'花菜原产地中海地区，近代传入中国。晚清文献开始出现相关记载，此后逐渐成为常见蔬菜。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-champa-rice-introduction','占城稻引入中国','agriculture','point','approximate_year',NULL,NULL,'宋真宗大中祥符五年（1012）遣使福建取占城稻并推广，是现存材料所见较早的大规模引种记载。',1012,12,NULL,12155,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'占城稻由越南中南部传入福建，具有早熟、耐旱等特点。北宋政府取种分发江淮、两浙推广，促进稻作复种和粮食增产。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-cotton-introduction','亚洲棉传入中国','agriculture','point','approximate_year',NULL,NULL,'人民论坛文章将亚洲棉引入中国置于西汉，具体年份未详。',-202,12,NULL,-2401,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'亚洲棉由印度方向传入中国，早期主要在边疆地区种植；宋元时期种植进一步向中原扩展，明代棉布逐渐成为重要衣料。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-crops-introduction','汉代作物传入','agriculture','point','approximate_year',NULL,NULL,'传统记述将部分作物的传入与汉代西域交流联系起来；具体年代和路线因作物及史料而异。',-138,12,NULL,-1633,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'黄瓜、葡萄、石榴、核桃、大蒜、胡荽、芝麻、苜蓿、胡椒、豌豆、蚕豆、豇豆等作物在汉代前后经陆上交通传播至中国。古代记载将其中若干种与西域交流联系起来；各作物的来源、传播路线和具体传入时间并不相同。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-eggplant-introduction','茄子传入中国','agriculture','point','approximate_year',NULL,NULL,'截图依据《齐民要术》列入魏晋南北朝时期；以该书成书约544年作为可核的早期栽培记载时点。',544,12,NULL,6539,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'茄子可能由南亚经贸易路线传入中国；魏晋南北朝农书《齐民要术》已有栽培记载，表明当时已在中国种植。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-fig-introduction','无花果传入中国','agriculture','point','approximate_year',NULL,NULL,'无花果入华年代记载不一，有魏晋南北朝传入说，亦有唐代盛行说；具体引种年份未详。',220,12,NULL,2651,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'无花果原产西亚，魏晋南北朝时期已在中国传播；后世文献和园艺栽培记载逐渐增多。具体最初传入时间仍有不同说法。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-luffa-introduction','丝瓜传入中国','agriculture','point','approximate_year',NULL,NULL,'丝瓜实际传入年份难以考定；现有材料显示宋代已有传播与栽培线索。',960,12,NULL,11531,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'丝瓜原产地通常认为在南亚，经陆上或海上交通传入中国南方。丝瓜至迟在宋代已有栽培，宋元时期逐步传播；具体传入年份和路线难以考定。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-onion-introduction','洋葱传入中国','agriculture','point','approximate_year',NULL,NULL,'资料称洋葱于清末传入中国，具体年份未详。',1840,12,NULL,22091,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'洋葱原产西亚及中亚，经近代贸易传播到中国，晚清后逐渐在各地种植和食用。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-peanut-introduction','花生传入中国','agriculture','point','approximate_year',NULL,NULL,'截图将花生列在明代中后期，并提及16世纪初经东南亚传播；取1500年作为其所述范围的最早年份，不视为确切首传年。',1500,12,NULL,18011,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'花生原产南美洲，明代经海路进入中国，随后逐渐成为重要油料和食用作物。早期引种路线与时间仍有不同说法。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-pineapple-introduction','菠萝（凤梨）传入中国','agriculture','point','approximate_year',NULL,NULL,'资料称菠萝于明末由南美传入中国，具体年份未详。',1600,12,NULL,19211,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'菠萝原产南美洲热带地区，经海路传入亚洲并进入中国南方。此后在岭南、台湾等地逐步栽培。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-potato-introduction','马铃薯传入中国','agriculture','point','approximate_year',NULL,NULL,'农业史年表将马铃薯传入中国记为17世纪中叶，具体年份未详。',1650,12,NULL,19811,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'马铃薯原产南美洲安第斯地区，明末清初传入中国，之后在西南、华北等地逐渐种植，成为重要的高产粮食作物。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-pumpkin-introduction','南瓜传入中国','agriculture','point','approximate_year',NULL,NULL,'资料将南瓜列入明代传入的美洲作物，具体传入年份未详，另有明代中后期传播说。',1500,12,NULL,18011,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'南瓜原产美洲，随跨洋贸易在明代传入中国，因适应性较强而传播到多地，成为蔬菜和粮食补充。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-spinach-introduction','菠菜传入中国','agriculture','point','approximate_year',NULL,NULL,'农业科技史年表将菠菜传入中国记为646年；采用该早期记载年份。',646,12,NULL,7763,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'菠菜原产西亚，经中亚、尼泊尔等地传播入唐。此后逐渐成为常见绿叶蔬菜。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-strawberry-introduction','现代草莓传入中国','agriculture','point','approximate_year',NULL,NULL,'现有资料将草莓引入中国置于近现代，尚无更早的确切年份记载。',1911,12,NULL,22943,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'现代栽培草莓由欧洲品种杂交培育而来，近代传入中国后逐步开展栽培，与中国原有野生草莓资源不同。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-sunflower-introduction','向日葵传入中国','agriculture','point','approximate_year',NULL,NULL,'资料将向日葵列入美洲作物输入中国的历史过程，具体传入年份未详。',1600,12,NULL,19211,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'向日葵原产北美洲，明清之际经跨洋贸易传入中国，后逐渐发展为观赏、食用和油料作物。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-watermelon-introduction','西瓜传入中国北方','agriculture','point','approximate_year',NULL,NULL,'农业科技史年表记953年胡桥将西瓜由回纥传入契丹地区；取该最早明确年份。',953,12,NULL,11447,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'西瓜源自非洲，经中亚向东传播。五代时期已有西瓜传入契丹地区的记载，之后逐步进入中原并广泛栽培。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-western-apple-introduction','西洋苹果传入中国','agriculture','point','approximate_year',NULL,NULL,'人民论坛文章称西洋苹果于19世纪中叶由传教士引入中国，具体年份未详。',1850,12,NULL,22211,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'近代西洋苹果品种由欧美传入中国，果肉和风味区别于传统本土苹果，随后在华北、西北等地发展种植。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('agri-zucchini-introduction','西葫芦传入中国','agriculture','point','approximate_year',NULL,NULL,'资料称西葫芦于清末由北美传入中国，具体年份未明。',1890,12,NULL,22691,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'西葫芦属于美洲南瓜类，现代栽培品种形成于欧洲，清末传入中国后逐渐成为常见蔬菜。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('commerce-chili-introduction','辣椒传入中国','agriculture','point','approximate_year',NULL,NULL,'辣椒首传路线和年份未详，研究常置于16世纪后期至17世纪前期；现有材料尚不能确定确切引入时间。',1570,12,NULL,18851,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'辣椒原产美洲，随跨洋贸易传入亚洲并进入中国。早期多作观赏或药用植物，之后逐渐进入饮食，在各地形成不同的食用习惯。中国首传的路线和年份尚不能确考。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('commerce-longqing-yuegang-opening','隆庆开海','commerce','point','year',NULL,NULL,'隆庆元年（1567）；采用海澄县志等记载的开港年份。',1567,12,NULL,18815,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'明廷在福建月港有限度开放民间海上贸易，商船可依规出洋，月港成为东南沿海重要贸易港。政策并未废除海禁，走私、朝贡贸易与许可贸易仍交织并存。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('commerce-maize-introduction','玉米传入中国','agriculture','point','approximate_year',NULL,NULL,'《巩县志》于1534年记“玉麦”，是现存较早的中国玉米文献记载之一；此记载不能确定实际传入年份。',1534,12,NULL,18419,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'玉米原产美洲，明代经海路及可能的陆路传入中国。1534年《巩县志》所见“玉麦”是早期记载之一；其耐旱、适应性强，后来在山地和旱地广泛种植。具体首传地点与路线尚有争议。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('commerce-qing-canton-system','广州一口通商','commerce','point','year',NULL,NULL,'乾隆二十二年（1757）政策转折；各口岸执行和限制逐渐落实，不将其解释为所有对外贸易一概中止。',1757,12,NULL,21095,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'清廷将西洋商船贸易集中于广州，外商主要通过广州行商体系交易。广州由此成为清代中西贸易的核心口岸，这一格局延续至鸦片战争前后。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('commerce-qing-maritime-trade-reopened','清廷开海','commerce','point','year',NULL,NULL,'康熙二十三年（1684）解除海禁、设置海关；开放港口的诏令及实施在1685年。',1684,12,NULL,20219,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'平定台湾后，清廷解除海禁并设粤、闽、浙、江四海关管理海上贸易与征税；次年开放广州、漳州、宁波、云台山等贸易港。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('commerce-song-guangzhou-shipping-office','广州设市舶司','commerce','point','year',NULL,NULL,'开宝四年（971）；广州博物馆所藏北宋《大宋新修广利王庙之碑》记载平南汉后设司。',971,12,NULL,11663,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'北宋平定南汉后在广州设置市舶司，专门管理海外商船、蕃货和贸易事务。此后宋廷陆续在东南沿海增设机构，海贸成为国家财政与跨区域交流的重要组成。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('commerce-song-tea-horse-trade','茶马互市兴起','commerce','point','year',NULL,NULL,'熙宁七年（1074）被视为宋代茶马制度形成的重要年份；贸易实践和机构调整持续多年。',1074,12,NULL,12899,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'宋廷在四川等地设置茶马贸易机构，以茶换取西北及西南地区所需战马，并以官府专營、茶引等方式管理交易。茶马互市把边疆贸易、軍需供给与区域治理联系起来。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('commerce-sweet-potato-introduction','甘薯经海路传入福建','agriculture','point','approximate_year',NULL,NULL,'福建引种记载有万历十年（1582）、万历十一至十二年及万历二十一年（1593）等说法；按要求取最早提及的1582年，保留不同记载的分歧。',1582,12,NULL,18995,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'甘薯原产美洲，经海上贸易网络传入福建。关于陈益、陈振龙等人的引种时间和路线，地方记载并不一致；甘薯耐瘠、高产，后来成为重要的粮食补充和救荒作物。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('commerce-tobacco-introduction','烟草传入中国','agriculture','point','approximate_year',NULL,NULL,'烟草传入时间有16至17世纪等说；1624年《景岳全书》追述万历年间闽、广已有烟草，尚不足以确定首传年份。',1540,12,NULL,18491,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'烟草原产美洲，经菲律宾吕宋及海上贸易网络传入中国，随后由东南沿海向内地传播。早期兼作药用，后来成为广泛种植和消费的经济作物。具体首传年份仍有争议。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('commerce-tomato-introduction','番茄传入中国','agriculture','point','approximate_year',NULL,NULL,'番茄传入中国的时间难以考定；周文华《汝南圃史·植品》（1617）记有番茄在华早期名称。',1617,12,NULL,19415,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'番茄原产美洲，随海上贸易传播至亚洲并传入中国。中国首传时间和路线未能确证；明代文献中的相关名称提供了早期在华线索，番茄初期较为稀见，后来才普遍成为食用蔬菜。',NULL,NULL,'[]');
